55	    55	    /// Consume one event. Returns the emitted ModelEvents (most calls
56	    56	    /// emit zero or one; `message_delta` carrying both stop_reason and
57	    57	    /// usage emits one Usage followed by Finish on `message_stop`). A
58	    58	    /// terminal event (`Finish` or an `Err`) is emitted at most once per
59	    59	    /// stream, and a later `message_delta`'s `Usage` is suppressed once one
60	    60	    /// has been emitted. Content deltas are deliberately *not* guarded: a
61	    61	    /// malformed stream that keeps sending `content_block_delta` after
62	    62	    /// `message_stop` would still yield them. A clean end-of-stream flush of
63	    63	    /// a buffered stop reason with no terminal event yet is handled
64	    64	    /// separately by `finish()`.
65	    65	    pub(crate) fn consume(
66	    66	        &mut self,
67	    67	        event: AnthropicEvent,
68	    68	    ) -> Result<Vec<Result<ModelEvent, ModelError>>, ModelError> {
69	    69	        let mut out: Vec<Result<ModelEvent, ModelError>> = Vec::new();
70	    70	        match event {
71	    71	            AnthropicEvent::MessageStart { message } => {
72	    72	                let MessageStartUsage {
73	    73	                    input_tokens,
74	    74	                    cache_read_input_tokens,
75	    75	                    ..
76	    76	                } = message.usage;
77	    77	                self.last_input_tokens = input_tokens;
78	    78	                self.last_cached_input_tokens = cache_read_input_tokens;
79	    79	                out.push(Ok(ModelEvent::Usage {
80	    80	                    input_tokens,
81	    81	                    output_tokens: 0,
82	    82	                    cached_input_tokens: cache_read_input_tokens,
83	    83	                    reasoning_tokens: None,
84	    84	                }));
85	    85	            }
86	    86	            AnthropicEvent::ContentBlockStart {
87	    87	                index,
88	    88	                content_block,
89	    89	            } => match content_block {
90	    90	                ContentBlockHead::Text => {
91	    91	                    self.blocks.insert(index, BlockState::Text);
92	    92	                }
93	    93	                ContentBlockHead::Thinking => {
94	    94	                    self.blocks.insert(index, BlockState::Thinking);
95	    95	                }
96	    96	                ContentBlockHead::ToolUse { id, name, .. } => {
97	    97	                    if self.synthesizing_output && name == SYNTHESIZED_TOOL_NAME {
98	    98	                        self.synthesized_tool_index = Some(index);
99	    99	                    } else {
100	   100	                        self.other_tool_fired = true;
101	   101	                    }
102	   102	                    self.blocks.insert(
103	   103	                        index,
104	   104	                        BlockState::ToolUse {
105	   105	                            call_id: id,
106	   106	                            name,
107	   107	                            name_emitted: false,
108	   108	                        },
109	   109	                    );
110	   110	                }
111	   111	            },
112	   112	            AnthropicEvent::ContentBlockDelta { index, delta } => match delta {
113	   113	                ContentBlockDelta::TextDelta { text } => {
114	   114	                    out.push(Ok(ModelEvent::TokenDelta { text }));
115	   115	                }
116	   116	                ContentBlockDelta::ThinkingDelta { thinking } => {
117	   117	                    out.push(Ok(ModelEvent::ReasoningDelta { text: thinking }));
118	   118	                }
119	   119	                ContentBlockDelta::SignatureDelta { .. } => {
120	   120	                    tracing::debug!(
121	   121	                        target: "paigasus::anthropic::stream",
122	   122	                        "signature_delta dropped (round-trip not yet supported)",
123	   123	                    );
124	   124	                }
125	   125	                ContentBlockDelta::InputJsonDelta { partial_json } => {
126	   126	                    let is_synth = Some(index) == self.synthesized_tool_index;
127	   127	                    if is_synth {
128	   128	                        out.push(Ok(ModelEvent::TokenDelta { text: partial_json }));
129	   129	                    } else if let Some(BlockState::ToolUse {
130	   130	                        call_id,
131	   131	                        name,
132	   132	                        name_emitted,
133	   133	                    }) = self.blocks.get_mut(&index)
134	   134	                    {
135	   135	                        let (emit_name, call_id_out) = if *name_emitted {
136	   136	                            (None, call_id.clone())
137	   137	                        } else {
138	   138	                            *name_emitted = true;
139	   139	                            (Some(name.clone()), call_id.clone())
140	   140	                        };
141	   141	                        out.push(Ok(ModelEvent::ToolCallDelta {
142	   142	                            call_id: call_id_out,
143	   143	                            name: emit_name,
144	   144	                            args_delta: partial_json,
145	   145	                        }));
146	   146	                    } else {
147	   147	                        // Protocol violation: input_json_delta only ever
148	   148	                        // applies to a tool_use content block. Surface it
149	   149	                        // rather than silently dropping (which would mask
150	   150	                        // a malformed upstream stream).
151	   151	                        return Err(ModelError::Transport(format!(
152	   152	                            "anthropic stream: input_json_delta at index {index} \
153	   153	                             has no preceding tool_use content_block_start"
154	   154	                        )));
155	   155	                    }
156	   156	                }
157	   157	            },
158	   158	            AnthropicEvent::ContentBlockStop { .. } => {
159	   159	                tracing::debug!(target: "paigasus::anthropic::stream", "content_block_stop");
160	   160	            }
161	   161	            AnthropicEvent::MessageDelta { delta, usage } => {
162	   162	                // A `message_delta` after the terminal event is a protocol
163	   163	                // violation (e.g. a second `message_delta` re-arming
164	   164	                // `stop_reason` post-`message_stop`, see
165	   165	                // `second_message_delta_after_message_stop_does_not_double_finish`).
166	   166	                // Emitting its `Usage` would put an event after `Finish`,
167	   167	                // which the core contract forbids.
168	   168	                if !self.terminal_emitted {
169	   169	                    if let Some(MessageDeltaUsage { output_tokens }) = usage {
170	   170	                        out.push(Ok(ModelEvent::Usage {
171	   171	                            input_tokens: self.last_input_tokens,
172	   172	                            output_tokens,
173	   173	                            cached_input_tokens: self.last_cached_input_tokens,
174	   174	                            reasoning_tokens: None,
175	   175	                        }));
176	   176	                    }
177	   177	                }
178	   178	                if let Some(reason) = delta.stop_reason {
179	   179	                    self.stop_reason = Some(reason);
180	   180	                }
