198	   198	    /// Flush a stop reason buffered from `message_delta` when the response
199	   199	    /// body ends cleanly before `message_stop` arrived.
200	   200	    ///
201	   201	    /// Returns `None` when a terminal event was already emitted — the
202	   202	    /// well-formed path, where `message_stop` drained the buffer — or when no
203	   203	    /// stop reason was ever observed. A stream that ended *before*
204	   204	    /// `message_delta` is never reported as a clean `Stop`; one that ended
205	   205	    /// *after* it is, because `message_delta`'s `stop_reason` is the model's
206	   206	    /// own authoritative decision and `message_stop` is only a frame
207	   207	    /// terminator.
208	   208	    ///
209	   209	    /// `terminal_emitted` — not `stop_reason` being `Some` — is the guard.
210	   210	    /// A second `message_delta` can re-arm the buffer after `message_stop`
211	   211	    /// already emitted, and that must not produce a second terminal event.
212	   212	    ///
213	   213	    /// **Clean-EOF path only.** Never call this on the cancellation or
214	   214	    /// transport-error paths — see `model.rs`.
215	   215	    pub(crate) fn finish(&mut self) -> Option<Result<ModelEvent, ModelError>> {
216	   216	        if self.terminal_emitted {
217	   217	            return None;
218	   218	        }
219	   219	        let reason = self.stop_reason.take()?;
220	   220	        self.terminal_emitted = true;
221	   221	        tracing::warn!(
222	   222	            target: "paigasus::anthropic::stream",
223	   223	            stop_reason = %reason,
224	   224	            "stream body ended without message_stop; flushing buffered stop reason",
225	   225	        );
226	   226	        Some(self.finish_or_error(&reason))
227	   227	    }
