229	   229	    fn finish_or_error(&self, reason: &str) -> Result<ModelEvent, ModelError> {
230	   230	        match reason {
231	   231	            "end_turn" | "stop_sequence" => Ok(ModelEvent::Finish {
232	   232	                reason: FinishReason::Stop,
233	   233	            }),
234	   234	            "max_tokens" => Ok(ModelEvent::Finish {
235	   235	                reason: FinishReason::Length,
236	   236	            }),
237	   237	            "tool_use" => {
238	   238	                if self.synthesizing_output && !self.other_tool_fired {
239	   239	                    Ok(ModelEvent::Finish {
240	   240	                        reason: FinishReason::Stop,
241	   241	                    })
242	   242	                } else if self.synthesizing_output && self.other_tool_fired {
243	   243	                    Err(ModelError::Other(anyhow::anyhow!(
244	   244	                        "structured output: model fired both a real tool and the synthesized output tool"
245	   245	                    )))
246	   246	                } else {
247	   247	                    Ok(ModelEvent::Finish {
248	   248	                        reason: FinishReason::ToolCalls,
249	   249	                    })
250	   250	                }
251	   251	            }
252	   252	            "refusal" => Err(ModelError::Refused {
253	   253	                reason: "model refused".to_owned(),
254	   254	            }),
255	   255	            other => Ok(ModelEvent::Finish {
256	   256	                reason: FinishReason::Other(other.to_owned()),
257	   257	            }),
258	   258	        }
259	   259	    }
260	   260	}
