  1	//! `Vec<Item>` + `ModelRequest` → Anthropic Messages request body.
  2	//!
  3	//! Rules per the SMA-317 spec § "Wire translation". The translator
  4	//! produces a `serde_json::Value` rather than typed structs to keep the
  5	//! wire-snapshot tests readable.
  6	
  7	use paigasus_helikon_core::{ContentPart, Item};
  8	use serde_json::{json, Value};
  9	
 10	/// Output of [`translate_messages`]: the top-level `system` field (string
 11	/// or block-array form) and the `messages` array.
 12	pub(crate) struct TranslatedMessages {
 13	    pub(crate) system: Option<Value>,
 14	    pub(crate) messages: Value,
 15	    /// `true` when the last user message produced no message, no kept
 16	    /// message or tool item follows it (dropped assistant items do not
 17	    /// count), and the last sent message is an assistant one.
 18	    pub(crate) trailing_message_dropped: bool,
 19	}
 20	
 21	/// Translate the conversation into Anthropic's request shape.
 22	///
 23	/// `system` is `None` when no `Item::System` has non-blank text. `messages`
 24	/// is always an array. Text parts that are empty or whitespace only, and
 25	/// messages left with no blocks, are dropped because the API rejects them.
 26	pub(crate) fn translate_messages(items: &[Item]) -> TranslatedMessages {
 27	    let mut system_text = String::new();
 28	    let mut messages: Vec<Value> = Vec::new();
 29	    let mut pending_tool_use: Vec<Value> = Vec::new();
 30	    let mut pending_tool_results: Vec<Value> = Vec::new();
 31	    let mut last_item_dropped = false;
 32	
 33	    fn flush_pending_assistant(messages: &mut Vec<Value>, pending: &mut Vec<Value>) {
 34	        if !pending.is_empty() {
 35	            messages.push(json!({
 36	                "role": "assistant",
 37	                "content": std::mem::take(pending),
 38	            }));
 39	        }
 40	    }
 41	
 42	    fn flush_pending_user(messages: &mut Vec<Value>, pending: &mut Vec<Value>) {
 43	        if !pending.is_empty() {
 44	            messages.push(json!({
 45	                "role": "user",
 46	                "content": std::mem::take(pending),
 47	            }));
 48	        }
 49	    }
 50	
 51	    /// Add `tool_use` blocks to the open assistant turn. When the last
 52	    /// message is an assistant message, extend it. Otherwise queue them.
 53	    fn push_tool_uses(
 54	        messages: &mut [Value],
 55	        pending_tool_use: &mut Vec<Value>,
 56	        blocks: Vec<Value>,
 57	    ) {
 58	        if let Some(last) = messages.last_mut().filter(|m| m["role"] == "assistant") {
 59	            last["content"].as_array_mut().unwrap().extend(blocks);
 60	        } else {
 61	            pending_tool_use.extend(blocks);
 62	        }
 63	    }
 64	
 65	    for item in items {
 66	        match item {
 67	            Item::System { content } => {
 68	                flush_pending_assistant(&mut messages, &mut pending_tool_use);
 69	                flush_pending_user(&mut messages, &mut pending_tool_results);
 70	                if !system_text.is_empty() {
 71	                    system_text.push('\n');
 72	                }
 73	                system_text.push_str(&text_of(content));
 74	            }
 75	            Item::UserMessage { content } => {
 76	                flush_pending_assistant(&mut messages, &mut pending_tool_use);
 77	                // Pending tool_results go at the front of this user turn.
 78	                let mut blocks: Vec<Value> = std::mem::take(&mut pending_tool_results);
 79	                blocks.extend(user_blocks(content).as_array().unwrap().iter().cloned());
 80	                last_item_dropped = blocks.is_empty();
 81	                if !blocks.is_empty() {
 82	                    messages.push(json!({"role": "user", "content": blocks}));
 83	                }
 84	            }
 85	            Item::AssistantMessage { content, agent: _ } => {
 86	                let Value::Array(blocks) = assistant_blocks(content) else {
 87	                    unreachable!("assistant_blocks returns an array")
 88	                };
 89	                // An assistant item with no blocks acts as if it were absent:
 90	                // it flushes nothing (so an open tool round stays whole) and
 91	                // leaves the flag as it is (a drop of the user turn before
 92	                // it still counts). A kept assistant message ends the drop.
 93	                //
 94	                // A message of only tool uses is the nested form of
 95	                // `Item::ToolCall`. Inside an open round it joins that round,
 96	                // as a call does. A flush would put a user turn that lacks
 97	                // some results right after the open assistant turn.
 98	                // On this path the last message is an assistant message
 99	                // (`round_is_answered` is `true` for an empty trailing
100	                // assistant run). `pending_tool_use` is empty, because each
101	                // `ToolResult` flushes it. So the append keeps the order.
102	                // Setting `last_item_dropped` here is for symmetry. The flag
103	                // is already `false`, because a `ToolResult` came after any
104	                // dropped user message.
105	                let only_tool_uses =
106	                    !blocks.is_empty() && blocks.iter().all(|b| b["type"] == "tool_use");
107	                if only_tool_uses
108	                    && !pending_tool_results.is_empty()
109	                    && !round_is_answered(&messages, &pending_tool_results)
110	                {
111	                    last_item_dropped = false;
112	                    push_tool_uses(&mut messages, &mut pending_tool_use, blocks);
113	                } else if !blocks.is_empty() {
114	                    flush_pending_assistant(&mut messages, &mut pending_tool_use);
115	                    flush_pending_user(&mut messages, &mut pending_tool_results);
116	                    last_item_dropped = false;
117	                    messages.push(json!({"role": "assistant", "content": blocks}));
118	                }
119	            }
120	            Item::ToolCall {
121	                call_id,
122	                name,
123	                args,
124	            } => {
125	                last_item_dropped = false;
126	                // A new tool_use follows any results already seen. Close
127	                // that user turn first only when the last assistant round is
128	                // fully answered; otherwise the call joins that round.
129	                if round_is_answered(&messages, &pending_tool_results) {
130	                    flush_pending_user(&mut messages, &mut pending_tool_results);
131	                }
132	                let block = json!({
133	                    "type": "tool_use",
134	                    "id": call_id,
135	                    "name": name,
136	                    "input": args,
137	                });
138	                push_tool_uses(&mut messages, &mut pending_tool_use, vec![block]);
139	            }
140	            Item::ToolResult { call_id, content } => {
141	                last_item_dropped = false;
142	                flush_pending_assistant(&mut messages, &mut pending_tool_use);
143	                pending_tool_results.push(json!({
144	                    "type": "tool_result",
145	                    "tool_use_id": call_id,
146	                    "content": text_of(content),
147	                }));
148	            }
149	            _ => {
150	                tracing::warn!(
151	                    target: "paigasus::anthropic::translate",
152	                    "unknown Item variant; skipping",
153	                );
154	            }
155	        }
156	    }
157	
158	    flush_pending_assistant(&mut messages, &mut pending_tool_use);
159	    flush_pending_user(&mut messages, &mut pending_tool_results);
160	
161	    let trailing_message_dropped =
162	        last_item_dropped && messages.last().is_some_and(|m| m["role"] == "assistant");
163	
164	    let system = if system_text.trim().is_empty() {
165	        None
166	    } else {
167	        Some(Value::String(system_text))
168	    };
169	    TranslatedMessages {
170	        system,
171	        messages: Value::Array(messages),
172	        trailing_message_dropped,
173	    }
174	}
175	
176	/// `true` when every `tool_use` id in the trailing run of assistant messages
177	/// has a matching `tool_result` in `results`. The API joins adjacent
178	/// assistant messages into one turn, so the whole run is one round. Also
179	/// `true` when there is nothing to compare (no assistant message last), so
180	/// the results then flush as before.
181	fn round_is_answered(messages: &[Value], results: &[Value]) -> bool {
182	    messages
183	        .iter()
184	        .rev()
185	        .take_while(|m| m["role"] == "assistant")
186	        .flat_map(|m| m["content"].as_array().into_iter().flatten())
187	        .filter(|b| b["type"] == "tool_use")
188	        .all(|b| results.iter().any(|r| r["tool_use_id"] == b["id"]))
189	}
