  1	//! `CacheStrategy` → cache_control marker placement.
  2	//!
  3	//! Anthropic accepts up to 4 cache breakpoints per request. Our placements
  4	//! top out at 3 (system + tools + last turn).
  5	
  6	use serde_json::{json, Value};
  7	
  8	use crate::settings::CacheStrategy;
  9	
 10	/// Apply the cache strategy to the request body in-place.
 11	///
 12	/// `system` is normalized into block-array form when a system marker is
 13	/// requested (Anthropic accepts a string OR an array; markers need the
 14	/// array form). Returns the (possibly converted) system value.
 15	pub(crate) fn apply_cache_strategy(
 16	    strategy: CacheStrategy,
 17	    system: Option<Value>,
 18	    tools: &mut Value,
 19	    messages: &mut Value,
 20	) -> Option<Value> {
 21	    let mark = || json!({"type": "ephemeral"});
 22	    let system = match strategy {
 23	        CacheStrategy::None => system,
 24	        CacheStrategy::System | CacheStrategy::SystemAndTools => system.map(|s| {
 25	            let mut blocks = match s {
 26	                Value::String(text) => vec![json!({"type": "text", "text": text})],
 27	                Value::Array(arr) => arr,
 28	                _ => return s,
 29	            };
 30	            if let Some(last) = blocks.last_mut() {
 31	                if let Some(obj) = last.as_object_mut() {
 32	                    obj.insert("cache_control".to_owned(), mark());
 33	                }
 34	            }
 35	            Value::Array(blocks)
 36	        }),
 37	        CacheStrategy::Tools | CacheStrategy::LastTurn => system,
 38	    };
 39	
 40	    if matches!(
 41	        strategy,
 42	        CacheStrategy::Tools | CacheStrategy::SystemAndTools
 43	    ) {
 44	        if let Some(arr) = tools.as_array_mut() {
 45	            if let Some(last) = arr.last_mut() {
 46	                if let Some(obj) = last.as_object_mut() {
 47	                    obj.insert("cache_control".to_owned(), mark());
 48	                }
 49	            }
 50	        }
 51	    }
 52	
 53	    if matches!(strategy, CacheStrategy::LastTurn) {
 54	        if let Some(arr) = messages.as_array_mut() {
 55	            if let Some(last_msg) = arr.last_mut() {
 56	                if let Some(blocks) = last_msg["content"].as_array_mut() {
 57	                    if let Some(last_block) = blocks.last_mut() {
 58	                        if let Some(obj) = last_block.as_object_mut() {
 59	                            obj.insert("cache_control".to_owned(), mark());
 60	                        }
 61	                    }
 62	                }
 63	            }
 64	        }
 65	    }
 66	
 67	    system
 68	}
 69	
 70	#[cfg(test)]
 71	mod tests {
 72	    use super::*;
 73	
 74	    fn mark() -> Value {
 75	        json!({"type": "ephemeral"})
 76	    }
 77	
 78	    #[test]
 79	    fn none_strategy_leaves_body_untouched() {
 80	        let mut tools = json!([{"name": "t1"}]);
 81	        let mut messages = json!([{"role": "user", "content": [{"type": "text", "text": "hi"}]}]);
 82	        let system = apply_cache_strategy(
 83	            CacheStrategy::None,
 84	            Some(Value::String("S".to_owned())),
 85	            &mut tools,
 86	            &mut messages,
 87	        );
 88	        assert_eq!(system, Some(Value::String("S".to_owned())));
 89	        assert!(tools[0].get("cache_control").is_none());
 90	        assert!(messages[0]["content"][0].get("cache_control").is_none());
 91	    }
 92	
 93	    #[test]
 94	    fn system_strategy_converts_string_to_array_and_marks_last_block() {
 95	        let mut tools = json!([]);
 96	        let mut messages = json!([]);
 97	        let system = apply_cache_strategy(
 98	            CacheStrategy::System,
 99	            Some(Value::String("S".to_owned())),
100	            &mut tools,
101	            &mut messages,
102	        );
103	        let arr = system.unwrap();
104	        assert_eq!(arr[0]["type"], "text");
105	        assert_eq!(arr[0]["text"], "S");
106	        assert_eq!(arr[0]["cache_control"], mark());
107	    }
108	
109	    #[test]
110	    fn tools_strategy_marks_last_tool() {
111	        let mut tools = json!([{"name": "a"}, {"name": "b"}]);
112	        let mut messages = json!([]);
113	        apply_cache_strategy(CacheStrategy::Tools, None, &mut tools, &mut messages);
114	        assert!(tools[0].get("cache_control").is_none());
115	        assert_eq!(tools[1]["cache_control"], mark());
116	    }
117	
118	    #[test]
119	    fn system_and_tools_marks_both() {
120	        let mut tools = json!([{"name": "a"}]);
121	        let mut messages = json!([]);
122	        let system = apply_cache_strategy(
123	            CacheStrategy::SystemAndTools,
124	            Some(Value::String("S".to_owned())),
125	            &mut tools,
126	            &mut messages,
127	        );
128	        assert_eq!(system.unwrap()[0]["cache_control"], mark());
129	        assert_eq!(tools[0]["cache_control"], mark());
130	    }
131	
132	    #[test]
133	    fn empty_system_and_tools_inserts_nothing() {
134	        let mut tools = json!([]);
135	        let mut messages = json!([]);
136	        let system = apply_cache_strategy(
137	            CacheStrategy::SystemAndTools,
138	            None,
139	            &mut tools,
140	            &mut messages,
141	        );
142	        assert!(system.is_none());
143	        assert_eq!(tools, json!([]));
144	    }
145	
146	    #[test]
147	    fn last_turn_marks_final_block_of_final_message() {
148	        let mut tools = json!([]);
149	        let mut messages = json!([
150	            {"role": "user", "content": [{"type": "text", "text": "first"}]},
151	            {"role": "user", "content": [{"type": "text", "text": "second"}]},
152	        ]);
153	        apply_cache_strategy(CacheStrategy::LastTurn, None, &mut tools, &mut messages);
154	        assert!(messages[0]["content"][0].get("cache_control").is_none());
155	        assert_eq!(messages[1]["content"][0]["cache_control"], mark());
156	    }
157	}
  1	//! Anthropic-specific configuration: prompt-caching strategy + extended thinking.
  2	
  3	/// Where to place `cache_control: {type: "ephemeral"}` markers in the request body.
  4	///
  5	/// **Default `None` is opt-out:** no markers, body byte-identical to the
  6	/// uncached path. Anthropic's prompt cache requires a per-model write
  7	/// minimum (~1024 tokens for Sonnet, ~2048 for Opus); below that, the
  8	/// strategy is a documented no-op and the cache simply does not write.
  9	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
 10	#[non_exhaustive]
 11	pub enum CacheStrategy {
 12	    /// No cache_control markers.
 13	    #[default]
 14	    None,
 15	    /// Mark the final block of `system:` as a cache breakpoint.
 16	    System,
 17	    /// Mark the final tool in `tools[]` as a cache breakpoint.
 18	    Tools,
 19	    /// Mark both system and the last tool.
 20	    SystemAndTools,
 21	    /// Mark the final message in `messages[]` (rolling cache).
 22	    LastTurn,
 23	}
 24	
 25	/// Configuration for Anthropic extended/adaptive thinking.
 26	///
 27	/// **Model compatibility:**
 28	/// - Claude Opus 4.7 rejects `Enabled { .. }` (400). Use `Adaptive`.
 29	/// - Sonnet/Opus 4.6 accept both but recommend `Adaptive`.
 30	/// - Older Claude 4 (4.5, 4.1) accept `Enabled` and recommend it.
 31	///
 32	/// Anthropic requires `budget_tokens < max_tokens` for `Enabled` but
 33	/// documents no absolute minimum; this crate does not enforce one.
 34	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
 35	#[non_exhaustive]
 36	pub enum ExtendedThinking {
 37	    /// No `thinking` field in the request.
 38	    #[default]
 39	    Disabled,
 40	    /// `thinking: { type: "enabled", budget_tokens: N }`.
 41	    Enabled {
 42	        /// Maximum tokens the model may spend on internal reasoning.
 43	        budget_tokens: u32,
 44	    },
 45	    /// `thinking: { type: "adaptive" }`. Model picks the budget.
 46	    Adaptive,
 47	}
 48	
 49	#[cfg(test)]
 50	mod tests {
 51	    use super::*;
 52	
 53	    #[test]
 54	    fn cache_strategy_default_is_none() {
 55	        assert_eq!(CacheStrategy::default(), CacheStrategy::None);
 56	    }
 57	
 58	    #[test]
 59	    fn extended_thinking_default_is_disabled() {
 60	        assert_eq!(ExtendedThinking::default(), ExtendedThinking::Disabled);
 61	    }
 62	
 63	    #[test]
 64	    fn extended_thinking_enabled_carries_budget() {
 65	        let t = ExtendedThinking::Enabled {
 66	            budget_tokens: 8192,
 67	        };
 68	        match t {
 69	            ExtendedThinking::Enabled { budget_tokens } => assert_eq!(budget_tokens, 8192),
 70	            _ => panic!("expected Enabled"),
 71	        }
 72	    }
 73	}

